// ============================================
// FILTER COURSE EXPIRING EVENTS
// ============================================

const items = $input.all();
const expiringEvents = [];

for (const item of items) {
  const data = item.json;

  // Parse event if stringified
  let event = data.event || data;
  if (typeof event === 'string') {
    try {
      event = JSON.parse(event);
    } catch (e) {
      continue;
    }
  }

  // Filter only course.access.expiring events
  if (event.event === 'course.access.expiring' || event.type === 'course.access.expiring') {
    expiringEvents.push({
      json: {
        event_id: data.id || `expiring_${Date.now()}`,
        event_type: 'course.access.expiring',
        guild_id: event.guild_id,
        user_id: event.data?.user_id || event.user_id,
        discord_id: event.data?.discord_id || event.discord_id,
        course_id: event.data?.course_id,
        course_name: event.data?.course_name || 'Cours',
        expires_at: event.data?.expires_at,
        days_until_expiration: event.data?.days_until_expiration || 7,
        notification_type: event.data?.notification_type || 'expires_soon',
        timestamp: event.timestamp || new Date().toISOString()
      }
    });
  }
}

return expiringEvents.length > 0 ? expiringEvents : [];

// ============================================
// PREPARE EXPIRING REMINDER EMBED
// ============================================

const data = $input.first().json;

// Format expiration date
const expiresAt = data.expires_at ? new Date(data.expires_at) : null;
const formattedDate = expiresAt 
  ? expiresAt.toLocaleDateString('fr-FR', { day: 'numeric', month: 'long', year: 'numeric' })
  : 'bientôt';

// Urgency based on days remaining
let urgencyEmoji = '📅';
let urgencyColor = 0x3498DB; // Blue
let urgencyText = `dans ${data.days_until_expiration} jours`;

if (data.days_until_expiration <= 1) {
  urgencyEmoji = '🚨';
  urgencyColor = 0xE74C3C; // Red
  urgencyText = 'DEMAIN';
} else if (data.days_until_expiration <= 3) {
  urgencyEmoji = '⚠️';
  urgencyColor = 0xF39C12; // Orange
  urgencyText = `dans ${data.days_until_expiration} jours`;
}

const embed = {
  title: `${urgencyEmoji} Ton accès expire ${urgencyText}`,
  description: `Ton accès au cours **${data.course_name}** arrive à expiration.`,
  color: urgencyColor,
  fields: [
    {
      name: '📚 Cours',
      value: data.course_name,
      inline: true
    },
    {
      name: '📆 Date d\'expiration',
      value: formattedDate,
      inline: true
    },
    {
      name: '💡 Que faire ?',
      value: 'Renouvelle ton accès pour continuer à apprendre !\nUtilise `/cours` pour voir les options.',
      inline: false
    }
  ],
  footer: {
    text: 'Ne perds pas ta progression !'
  },
  timestamp: data.timestamp
};

const urgency = data.days_until_expiration <= 1 ? 'critical' : (data.days_until_expiration <= 3 ? 'warning' : 'info');

// RFC-030: Format pour notifications:stream
return {
  type: 'dm',
  guild_id: data.guild_id,
  discord_id: data.discord_id,
  content: `<@${data.discord_id}>`,
  embed: embed,
  notification_type: 'course_expiring',
  urgency: urgency,
  source: 'n8n:NOTIF-Course-Expiring',
  event_id: data.event_id,
  timestamp: new Date().toISOString()
};

// ============================================
// LOG NOTIFICATION PUBLISHED
// ============================================

const response = $input.first().json;
const prepData = $('Prepare Notification Payload').first().json;

console.log(`Course expiring notification published to stream for user ${prepData.discord_id} (urgency: ${prepData.urgency})`);

return {
  success: true,
  event_id: prepData.event_id,
  discord_id: prepData.discord_id,
  guild_id: prepData.guild_id,
  notification_type: 'course_expiring',
  urgency: prepData.urgency,
  stream: 'notifications:stream'
};
